 con.register('trips',d);cube=con.execute('SELECT hour,weekday,zone,payment,COUNT(*) AS count,SUM(fare_amount) AS fare,SUM(trip_distance) AS distance,SUM(duration) AS duration FROM trips GROUP BY ALL ORDER BY hour,weekday,zone,payment').df()
 hourly=d.groupby('hour').size();peak=hourly.idxmax();daily=d.groupby(d.lpep_pickup_datetime.dt.date).size();zone_table=d.groupby('zone').agg(trips=('count','sum'),mean_miles=('trip_distance','mean'),mean_minutes=('duration','mean'),mean_fare_usd=('fare_amount','mean')).sort_values('trips',ascending=False).head(12).round(2).reset_index()
